    /// <summary> Получает или устанавливает значение кредитного плеча. Допустимый диапазон: ["2" .. "10"] </summary>
/// <param name="_leverage"> Уровень кредитного плеча (целое число в виде строки) </param>
/// <returns> Уровень кредитного плеча </returns>
[DataMember('leverage')]
public str parmLeverage(str _leverage = leverage)
{
    leverage = _leverage;
    return leverage;
}

